static inline int z_impl_can_get_state(const struct device *dev, enum can_state *state,
				       struct can_bus_err_cnt *err_cnt)
{
	enum can_state tmp_state;
	struct can_bus_err_cnt tmp_err_cnt;

	/*
	 * The CAN API allows passing NULL for output parameters 'state' and 'err_cnt'.
	 * Ensure the driver's implementation always receives valid pointers to write to,
	 * even if the caller passes NULL. The values written to temporary variables
	 * will be discarded if the original pointers were NULL, which is the expected
	 * behavior.
	 */
	return DEVICE_API_GET(can, dev)->get_state(dev,
						  state != NULL ? state : &tmp_state,
						  err_cnt != NULL ? err_cnt : &tmp_err_cnt);
}
